  const rows=[['¿conservativo?',K.cons?'sí: F = ∇f':'no',K.cons?'ok':'no'],['fondo',K.lab||'—']];
  if(hov){const[x,y]=hov,[u,v]=K.F(x,y),e=1e-4,Py=(K.F(x,y+e)[0]-K.F(x,y-e)[0])/(2*e),Qx=(K.F(x+e,y)[1]-K.F(x-e,y)[1])/(2*e);rows.unshift(['punto',pt(x,y)],['F',pt(u,v)],['|F|',fmt(Math.hypot(u,v),3)],['∂P/∂y vs ∂Q/∂x',fmt(Py,3)+' vs '+fmt(Qx,3),Math.abs(Py-Qx)<1e-3?'ok':'no'])}
