  for(let i=0;i<N;i++){const g=S[i].g;c.strokeStyle=work?rgba(g>=0?Rr:A,.35+.65*Math.abs(g)/(gm||1)):rgba(I,.85);c.lineWidth=work?5:2+5*rho(...S[i].p)/5;c.lineCap='round';c.beginPath();c.moveTo(V.X(S[i].p[0]),V.Y(S[i].p[1]));c.lineTo(V.X(S[i+1].p[0]),V.Y(S[i+1].p[1]));c.stroke()}
  const e1=S[N-6].p,e2=S[N].p;if(sc.value!=='circ')arrow(c,V.X(e1[0]),V.Y(e1[1]),V.X(e2[0]),V.Y(e2[1]),C('ink'),2.5);else{const m1=S[Math.round(N*.25)-4].p,m2=S[Math.round(N*.25)+4].p;arrow(c,V.X(m1[0]),V.Y(m1[1]),V.X(m2[0]),V.Y(m2[1]),C('ink'),2.5)}
