  const t=+stt.value,i=Math.round(t*N),q=S[i],m=Math.hypot(...q.dr)||1,Tn=[q.dr[0]/m,q.dr[1]/m],X=V.X(q.p[0]),Y=V.Y(q.p[1]);
  arrow(c,X,Y,V.X(q.p[0]+.7*Tn[0]),V.Y(q.p[1]+.7*Tn[1]),C('ink'),2.5);const Fm=Math.hypot(...q.F);if(Fm>1e-6){const L=cl(Fm*.35,.3,1.3);arrow(c,X,Y,V.X(q.p[0]+L*q.F[0]/Fm),V.Y(q.p[1]+L*q.F[1]/Fm),C('y'),3)}dot(c,X,Y,6,C('ink'),C('paper'));c.restore();
  const top=MH+8,pad=14;let lo=Math.min(0,...G),hi=Math.max(0,...G);if(hi-lo<1e-9)hi=lo+1;const sx=s=>pad+s*(W-2*pad),sy=v=>top+SH-8-(v-lo)/(hi-lo)*(SH-16);
  c.fillStyle=C('bg');c.fillRect(0,top,W,SH);c.strokeStyle=C('line');c.lineWidth=1;c.strokeRect(.5,top+.5,W-1,SH-1);c.beginPath();c.moveTo(pad,sy(0));c.lineTo(W-pad,sy(0));c.stroke();
  c.strokeStyle=C('ink');c.lineWidth=2;c.beginPath();G.forEach((v,k)=>k?c.lineTo(sx(k/N),sy(v)):c.moveTo(sx(0),sy(v)));c.stroke();dot(c,sx(t),sy(G[i]),5,C('r'),C('paper'));
  const rows=[['t',fmt(t,3)],['r(t)',pt(...q.p)],[work?'F · r′(t)':'ρ |r′(t)|',fmt(q.g,3)],['acumulado hasta t',fmt(G[i],4)],[work?'∫_C F · dr (total)':'∫_C ρ ds (total)',fmt(tot,4),'ok'],['orientación',rev?'invertida':'original']];
